  function uses12HourClock(){try{return ['h11','h12'].includes(new Intl.DateTimeFormat(locale(),{hour:'numeric'}).resolvedOptions().hourCycle);}catch(e){return true;}}
  const $ = (selector, root=document) => root.querySelector(selector);
  const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
  const today = new Date();
